window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-61bea6446ce8eaac"]={"versions": [{"id": "FIG-61bea6446ce8eaac", "releases": ["R21-11", "R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Zeitablaufdiagramm / Task-Execution-Timeline (Trace-Modell) auf Einzelkernebene mit Präemptions- und Busy-Wait-Phasen.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform OS (Subsystem Multicore-Synchronisation). Das Diagramm visualisiert das Fehlerszenario eines <strong>Interferenz-Deadlocks</strong> (uniprocessor-typische Prioritätsinversion bei Busy-Waiting), wenn ein Spinlock kernlokal zwischen Tasks unterschiedlicher Priorität ohne ausreichende Präemptionssperre geteilt wird.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Entitäten:</strong></li>\n<li><code>Core 0</code>: Physischer Prozessorkern, auf dem beide Tasks im selben Kernkontext ausgeführt werden.</li>\n<li><code>Task low</code>: Niedrigpriorisierter, verdrängbarer OS-Task.</li>\n<li><code>Task high</code>: Hochpriorisierter OS-Task mit Verdrängungsrecht gegenüber <code>Task low</code>.</li>\n<li>Spinlock <code>A</code> (<code>SpinlockIdType</code>): Multicore-Synchronisationsobjekt im Shared Memory.</li>\n<li><strong>Schnittstellen & Betriebssystem-APIs:</strong></li>\n<li><code>StatusType GetSpinlock(SpinlockIdType SpinlockId)</code>: Synchroner OS-Dienst zur Belegung des Spinlocks via aktiver Warteschleife (Busy-Wait).</li>\n<li><code>StatusType ReleaseSpinlock(SpinlockIdType SpinlockId)</code>: Synchroner OS-Dienst zur Freigabe des Spinlocks.</li>\n<li>OS-Scheduler: Verantwortlich für den Kontextwechsel am Verdrängungspunkt (<em>Point of preemption</em>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Lock-Akquisition (Task low):</strong> <code>Task low</code> ruft <code>GetSpinlock(A)</code> auf, belegt den Spinlock <code>A</code> und betritt seinen kritischen Abschnitt (<em>Do something</em>).</li>\n<li><strong>Präemption:</strong> Während des kritischen Abschnitts wird <code>Task low</code> durch die Aktivierung oder das Event von <code>Task high</code> verdrängt (<em>Point of preemption</em>). <code>Task low</code> verbleibt im Zustand <code>READY</code>, hält jedoch weiterhin Spinlock <code>A</code>.</li>\n<li><strong>Ausführung & Verriegelungsversuch (Task high):</strong> <code>Task high</code> wird auf <code>Core 0</code> aktiv (<em>RUNNING</em>), führt unkritischen Code aus und setzt danach den Aufruf <code>GetSpinlock(A)</code> ab.</li>\n<li><strong>Interferenz-Deadlock (Spin for lock A):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Da <code>Task low</code> Spinlock <code>A</code> hält und durch <code>Task high</code> auf demselben Kern verdrängt ist, kann <code>Task low</code> die CPU nicht nutzen, um <code>ReleaseSpinlock(A)</code> auszuführen.</li>\n<li><code>Task high</code> verharrt in der aktiven Warteschleife auf <code>Core 0</code> und blockiert die CPU dauerhaft.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abbruchbedingung & Status-Rückgabe:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Im <code>EXTENDED</code>-Status erkennt das AUTOSAR OS, dass der angeforderte Spinlock bereits von einem Task/ISR auf demselben Kern gehalten wird (<code>[SWS_Os_00650]</code>).</li>\n<li>Die Warteschleife wird vermieden; der zweite <code>GetSpinlock(A)</code>-Aufruf bricht deterministisch mit dem Fehlerstatus <strong><code>E_OS_INTERFERENCE_DEADLOCK</code></strong> ab.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsvorgabe (<code>OsSpinlockLockMethod</code>):</strong></li>\n<li>Spinlocks, die von verdrängbaren Tasks auf demselben Kern genutzt werden, dürfen nicht mit <code>LOCK_NOTHING</code> konfiguriert werden, wenn höherpriorisierte Tasks denselben Spinlock anfordern können.</li>\n<li>Bei kernlokalem Ressourcenwettbewerb sind Standard-OSEK-Ressourcen (<code>GetResource</code> / <code>ReleaseResource</code> mit Priority Ceiling Protocol) normativ vorgeschrieben, da PCP Verdrängungen innerhalb des kritischen Abschnitts durch konkurrierende Tasks verhindert.</li>\n<li><strong>Fehlerbehandlung im API-Vertrag:</strong></li>\n<li>Der Rückgabewert von <code>GetSpinlock()</code> muss im Treiber- und Applikationscode zwingend auf <code>E_OS_INTERFERENCE_DEADLOCK</code> und <code>E_OS_NESTING_DEADLOCK</code> geprüft werden.</li>\n<li>Im Fehlerfall darf der kritische Abschnitt nicht betreten und keinesfalls <code>ReleaseSpinlock()</code> aufgerufen werden.</li>\n<li><strong>Timing & Watchdog-Überwachung:</strong></li>\n<li>Im <code>STANDARD</code>-Status (ohne erweiterte OS-Prüfungen) führt dieses Szenario zum Hängenbleiben des Kerns und zwingt die Watchdog-Überwachung (WdgM / Alive Supervision) in einen Partition- oder ECU-Reset.</li>\n</ul>"}, {"id": "FIG-d0d6f1adab59c881", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Zeitablaufdiagramm / Task-Execution-Timeline (Trace-Modell) auf Einzelkernebene mit Präemptions- und Busy-Wait-Phasen.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform OS (Subsystem Multicore-Synchronisation). Das Diagramm visualisiert das Fehlerszenario eines <strong>Interferenz-Deadlocks</strong> (uniprocessor-typische Prioritätsinversion bei Busy-Waiting), wenn ein Spinlock kernlokal zwischen Tasks unterschiedlicher Priorität ohne ausreichende Präemptionssperre geteilt wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Entitäten:</strong></li>\n<li><code>Core 0</code>: Physischer Prozessorkern, auf dem beide Tasks im selben Kernkontext ausgeführt werden.</li>\n<li><code>Task low</code>: Niedrigpriorisierter, verdrängbarer OS-Task.</li>\n<li><code>Task high</code>: Hochpriorisierter OS-Task mit Verdrängungsrecht gegenüber <code>Task low</code>.</li>\n<li>Spinlock <code>A</code> (<code>SpinlockIdType</code>): Multicore-Synchronisationsobjekt im Shared Memory.</li>\n<li><strong>Schnittstellen & Betriebssystem-APIs:</strong></li>\n<li><code>StatusType GetSpinlock(SpinlockIdType SpinlockId)</code>: Synchroner OS-Dienst zur Belegung des Spinlocks via aktiver Warteschleife (Busy-Wait).</li>\n<li><code>StatusType ReleaseSpinlock(SpinlockIdType SpinlockId)</code>: Synchroner OS-Dienst zur Freigabe des Spinlocks.</li>\n<li>OS-Scheduler: Verantwortlich für den Kontextwechsel am Verdrängungspunkt (<em>Point of preemption</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Lock-Akquisition (Task low):</strong> <code>Task low</code> ruft <code>GetSpinlock(A)</code> auf, belegt den Spinlock <code>A</code> und betritt seinen kritischen Abschnitt (<em>Do something</em>).</li>\n<li><strong>Präemption:</strong> Während des kritischen Abschnitts wird <code>Task low</code> durch die Aktivierung oder das Event von <code>Task high</code> verdrängt (<em>Point of preemption</em>). <code>Task low</code> verbleibt im Zustand <code>READY</code>, hält jedoch weiterhin Spinlock <code>A</code>.</li>\n<li><strong>Ausführung & Verriegelungsversuch (Task high):</strong> <code>Task high</code> wird auf <code>Core 0</code> aktiv (<em>RUNNING</em>), führt unkritischen Code aus und setzt danach den Aufruf <code>GetSpinlock(A)</code> ab.</li>\n<li><strong>Interferenz-Deadlock (Spin for lock A):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Da <code>Task low</code> Spinlock <code>A</code> hält und durch <code>Task high</code> auf demselben Kern verdrängt ist, kann <code>Task low</code> die CPU nicht nutzen, um <code>ReleaseSpinlock(A)</code> auszuführen.</li>\n<li><code>Task high</code> verharrt in der aktiven Warteschleife auf <code>Core 0</code> und blockiert die CPU dauerhaft.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abbruchbedingung & Status-Rückgabe:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Im <code>EXTENDED</code>-Status erkennt das AUTOSAR OS, dass der angeforderte Spinlock bereits von einem Task/ISR auf demselben Kern gehalten wird (<code>[SWS_Os_00650]</code>).</li>\n<li>Die Warteschleife wird vermieden; der zweite <code>GetSpinlock(A)</code>-Aufruf bricht deterministisch mit dem Fehlerstatus <strong><code>E_OS_INTERFERENCE_DEADLOCK</code></strong> ab.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsvorgabe (<code>OsSpinlockLockMethod</code>):</strong></li>\n<li>Spinlocks, die von verdrängbaren Tasks auf demselben Kern genutzt werden, dürfen nicht mit <code>LOCK_NOTHING</code> konfiguriert werden, wenn höherpriorisierte Tasks denselben Spinlock anfordern können.</li>\n<li>Bei kernlokalem Ressourcenwettbewerb sind Standard-OSEK-Ressourcen (<code>GetResource</code> / <code>ReleaseResource</code> mit Priority Ceiling Protocol) normativ vorgeschrieben, da PCP Verdrängungen innerhalb des kritischen Abschnitts durch konkurrierende Tasks verhindert.</li>\n<li><strong>Fehlerbehandlung im API-Vertrag:</strong></li>\n<li>Der Rückgabewert von <code>GetSpinlock()</code> muss im Treiber- und Applikationscode zwingend auf <code>E_OS_INTERFERENCE_DEADLOCK</code> und <code>E_OS_NESTING_DEADLOCK</code> geprüft werden.</li>\n<li>Im Fehlerfall darf der kritische Abschnitt nicht betreten und keinesfalls <code>ReleaseSpinlock()</code> aufgerufen werden.</li>\n<li><strong>Timing & Watchdog-Überwachung:</strong></li>\n<li>Im <code>STANDARD</code>-Status (ohne erweiterte OS-Prüfungen) führt dieses Szenario zum Hängenbleiben des Kerns und zwingt die Watchdog-Überwachung (WdgM / Alive Supervision) in einen Partition- oder ECU-Reset.</li>\n</ul>"}], "trans": [{"from": "FIG-61bea6446ce8eaac", "to": "FIG-d0d6f1adab59c881", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d0d6f1adab59c881", "to": "FIG-61bea6446ce8eaac", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
